  "keywords": [
    "html-to-video",
    "html-to-mp4",
    "programmatic-video",
    "multi-scene",
    "kinetic-typography",
    "video-rendering",
    "video",
    "canvas",
    "animation",
    "ffmpeg",
    "playwright",
    "deterministic",
    "agent-skill"
  ],
  "license": "MIT",
  "author": "wx4766",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wx4766/html-to-video.git"
  },
  "homepage": "https://github.com/wx4766/html-to-video#readme",
  "bugs": {
    "url": "https://github.com/wx4766/html-to-video/issues"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "test": "node --test",
    "test:smoke": "node --test test/render-smoke.test.mjs",
    "render": "node scripts/render-video-seek.js",
    "qa": "node scripts/qa.js",
    "bench": "node scripts/bench.js"
  },
  "devDependencies": {
    "playwright": "^1.49.1"
  }
}
